<script>
  import { canManage,canOperate } from './cockpit.js'
  import Modal from './CockpitModal.svelte'
  import { onMount } from 'svelte'
  import { apiGet, apiPost, apiPut, apiDelete } from './api.js'
  import { url, LEVEL } from './cockpit.js'
  import { fmtDateTime } from './product.js'
  let { tenant } = $props()
  let data = $state({ rules:[],history:[],areas:[] }), error = $state(''), busy = $state(false), q = $state(''), tab = $state('rules'), edit = $state(null), removing = $state(null)
  let shown = $derived(data.rules.filter(r => !q || `${r.name} ${r.description}`.toLowerCase().includes(q.toLowerCase())))
  async function load() { try { data = await apiGet(url(tenant.id,'alarms')) } catch(e) { error = e.message } }
  async function save(rule = edit) { busy = true; error = ''; try { await apiPut(url(tenant.id,`alarms/${encodeURIComponent(rule.id || 'new')}`), rule); edit = null; await load() } catch(e) { error = e.message }; busy = false }
  async function check() { busy = true; error = ''; try { await apiPost(url(tenant.id,'alarms/check')); tab = 'history'; await load() } catch(e) { error = e.message }; busy = false }
  async function remove() { busy = true; try { await apiDelete(url(tenant.id,`alarms/${encodeURIComponent(removing.id)}`)); removing = null; await load() } catch(e) { error = e.message }; busy = false }
  onMount(load)
</script>
<div class="cp-head"><div><h2>Alarm-Regeln</h2><p>{tenant.name} · Auslöser, Schwellwerte und Verlauf</p></div><div class="cp-actions"><button class="btn btn-secondary" disabled={busy || !canOperate(tenant)} onclick={check}>Jetzt prüfen</button><button class="btn btn-primary" disabled={!canManage(tenant)} onclick={() => edit = { name:'',description:'',area:'',severity:'high',threshold:1,enabled:true }}>+ Regel erstellen</button></div></div>
<div class="cp-note">Regeln prüfen offene Managed-Service-Befunde und erzeugen interne Alarmereignisse beim Überschreiten des Schwellwerts. Automatische Prüfungen erfolgen nach einer Managed-Service-Erhebung. Den Erhebungszeitplan und bestehende Teams-Benachrichtigungen konfigurierst du im Managed Service.</div>
{#if error}<div class="cp-note cp-gaps" role="alert">{error}</div>{/if}
<div class="cp-tabs"><button class:active={tab === 'rules'} onclick={() => tab = 'rules'}>Regeln ({data.rules.length})</button><button class:active={tab === 'history'} onclick={() => tab = 'history'}>Verlauf</button></div>
{#if tab === 'rules'}<div class="cp-panel cp-toolbar"><input type="search" bind:value={q} placeholder="Name oder Beschreibung suchen…" aria-label="Regeln suchen"/></div>{#each shown as r}<section class="cp-panel cp-rule"><div><h3>{r.name}</h3><p>{r.description}</p><span class="cp-sub">{data.areas.find(a => a.id === r.area)?.label || 'Alle Bereiche'} · mindestens {r.threshold} Befund(e) ab {LEVEL[r.severity]}</span></div><div class="cp-actions"><span class="cp-badge {r.severity}">{LEVEL[r.severity]}</span><label><input type="checkbox" checked={r.enabled} disabled={busy || !canManage(tenant)} onchange={() => save({ ...r,enabled:!r.enabled })}/>Aktiv</label><button class="btn btn-secondary" disabled={!canManage(tenant)} onclick={() => edit = { ...r }}>Bearbeiten</button><button class="btn btn-secondary" disabled={!canManage(tenant)} onclick={() => removing = r}>Löschen</button></div></section>{:else}<div class="cp-empty">Keine Regeln vorhanden. Erstelle eine Regel für einen Bereich und Schweregrad.</div>{/each}
{:else}<div class="cp-table-wrap"><table><thead><tr><th>Zeitpunkt</th><th>Regel</th><th>Befunde</th><th>Ergebnis</th></tr></thead><tbody>{#each data.history as h}<tr><td>{fmtDateTime(h.at)}</td><td>{h.name}</td><td>{h.count}</td><td><span class="cp-badge" class:high={h.triggered}>{h.triggered ? 'Ausgelöst' : 'Unter Schwellwert'}</span></td></tr>{:else}<tr><td colspan="4">Noch keine Prüfungen.</td></tr>{/each}</tbody></table></div>{/if}
{#if edit}<Modal {error} label="Alarmregel bearbeiten" onclose={() => edit = null} busy={busy}><h3>{edit.id ? 'Regel bearbeiten' : 'Regel erstellen'}</h3><label>Regelname<input bind:value={edit.name} maxlength="120"/></label><label>Beschreibung<textarea bind:value={edit.description} maxlength="1000"></textarea></label><label>Auslöser / Bereich<select bind:value={edit.area}><option value="">Alle Bereiche</option>{#each data.areas as a}<option value={a.id}>{a.label}</option>{/each}</select></label><label>Schweregrad ab<select bind:value={edit.severity}>{#each Object.entries(LEVEL) as [id,label]}<option value={id}>{label}</option>{/each}</select></label><label>Schwellwert<input type="number" min="1" max="10000" bind:value={edit.threshold}/></label><div class="cp-actions"><button class="btn btn-secondary" disabled={busy} onclick={() => edit = null}>Abbrechen</button><button class="btn btn-primary" disabled={busy || !edit.name.trim()} onclick={() => save()}>Speichern</button></div></Modal>{/if}
{#if removing}<Modal {error} label="Regel löschen" onclose={() => removing = null} busy={busy}><h3>Regel löschen?</h3><p>{removing.name}</p><div class="cp-actions"><button class="btn btn-secondary" disabled={busy} onclick={() => removing = null}>Abbrechen</button><button class="btn btn-primary" disabled={busy} onclick={remove}>Löschen</button></div></Modal>{/if}
